import sys

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        n = int(next(iterator))
        T = int(next(iterator))
        t = []
        for _ in range(n):
            t.append(int(next(iterator)))
    except StopIteration:
        return

    count = 0
    current_time = 0

    for i in range(n):
        pos = i + 1
        arrival_time = pos
        if arrival_time >= T:
            break

        wait_until = t[i]

        if arrival_time >= wait_until:
            count += 1
            current_time = arrival_time
        else:
            finish_time = wait_until
            if finish_time < T:
                count += 1
                current_time = finish_time
            else:
                pass

    print(count)

if __name__ == "__main__":
    main()
